insert into public.stadiums (id, name, prefecture, address, lat, lng, stations, airports, access_url, shuttle_note, parking_note, agoda_area, verified_at) values ('sunpro-alwin', 'サンプロ アルウィン', '長野県', '長野県松本市神林5300 松本平広域公園内', 36.1797028, 137.9171639, '[{"name":"松本","kind":"shuttle","walk_min":null,"note":"松本バスターミナル（松本駅から徒歩3分）から無料シャトルバス約30分。往路はキックオフの4時間前〜45分前に30分おき","toyoko":[{"hotel":"00314","name":"東横INN松本駅東口","walk_min":3},{"hotel":"00102","name":"東横INN松本駅前本町","walk_min":6}]},{"name":"村井","kind":"nearest","walk_min":90,"note":"徒歩約1時間30分（4.7km）","toyoko":[]}]'::jsonb, '[]'::jsonb, 'https://www.yamaga-fc.com/stadium/access', '無料シャトルバスは松本バスターミナル発（往路：キックオフの4時間前〜45分前に30分おき、復路：試合終了後〜1時間後まで）。有料予約制バス（アルピコプラザホテル前発）もある。試合ごとに変わるので、松本山雅FC公式の「アクセス情報」で確かめる', '大芝生駐車場（約2,000台）など。試合によって使える駐車場が変わり、満車の情報は松本山雅FC公式Xで出る', '{"type":"city","id":23118,"name":"松本"}'::jsonb, '2026-11-07') on conflict do nothing;
insert into public.stadiums (id, name, prefecture, address, lat, lng, stations, airports, access_url, shuttle_note, parking_note, agoda_area, verified_at) values ('rohto-field-nara', 'ロートフィールド奈良', '奈良県', '奈良県奈良市法蓮佐保山四丁目5番1号', 34.6985083, 135.829194, '[{"name":"近鉄奈良","kind":"nearest","walk_min":20,"note":"徒歩約20分（1.6km）。路線バスなら13番のりばから「市営球場」下車、徒歩3分","toyoko":[{"hotel":"00249","name":"東横INN近鉄奈良駅前","walk_min":1}]},{"name":"奈良","kind":"bus","walk_min":null,"note":"JR奈良駅西口15番のりばから奈良交通バスで「市営球場」下車、徒歩3分","toyoko":[]}]'::jsonb, '[]'::jsonb, 'https://naraclub.jp/stadium/rohtonara', 'シャトルバスの案内はない（2026-11-07 時点）', 'ロート鴻池パーク中央駐車場（約250台）は早く満車になる。ドリームランド跡地駐車場（有料・徒歩約5分）は事前の申し込み', '{"type":"city","id":13313,"name":"奈良"}'::jsonb, '2026-11-07') on conflict do nothing;
insert into public.stadiums (id, name, prefecture, address, lat, lng, stations, airports, access_url, shuttle_note, parking_note, agoda_area, verified_at) values ('gifu-memorial', 'ヒマラヤスタジアム岐阜', '岐阜県', '岐阜県岐阜市長良福光大野2675-28', 35.4413, 136.7661, '[{"name":"岐阜","kind":"bus","walk_min":null,"note":"JR岐阜駅のバスターミナル10番（三田洞線）で「岐阜メモリアルセンター前」、11番（市内ループ線）で「岐阜メモリアルセンター北」下車。約20分・250円。試合日は増便","toyoko":[{"hotel":"00375","name":"東横INN岐阜","walk_min":10}]},{"name":"名鉄岐阜","kind":"bus","walk_min":null,"note":"名鉄岐阜バスターミナル4番（市内ループ線左回り）で「岐阜メモリアルセンター北」下車","toyoko":[]}]'::jsonb, '[]'::jsonb, 'https://www.fc-gifu.com/watching/stadium_access/', '無料のシャトルバスはない。試合日は JR岐阜駅発の路線バス（有料）が増える', '周辺の駐車場は混みやすい。akippa で事前予約ができる。臨時駐車場は試合によってだけ開く', '{"type":"city","id":10163,"name":"岐阜"}'::jsonb, '2026-11-07') on conflict do nothing;
insert into public.stadiums (id, name, prefecture, address, lat, lng, stations, airports, access_url, shuttle_note, parking_note, agoda_area, verified_at) values ('shiranami-stadium', '白波スタジアム', '鹿児島県', '鹿児島県鹿児島市与次郎2-2-2', 31.5648306, 130.5601861, '[{"name":"鹿児島中央","kind":"bus","walk_min":null,"note":"市営バス16番（鴨池港行）・27番（与次郎一丁目行）で約20〜30分、「KKB前」か「市民文化ホール前」下車すぐ","toyoko":[{"hotel":"00220","name":"東横INN鹿児島中央駅西口","walk_min":1},{"hotel":"00202","name":"東横INN鹿児島中央駅東口","walk_min":2}]},{"name":"騎射場","kind":"nearest","walk_min":17,"note":"市電1系統の電停。郡元電停も近い","toyoko":[]}]'::jsonb, '[{"iata":"KOJ","name":"鹿児島空港","station":null,"access_min":70,"note":"リムジンバスで鹿児島中央駅まで約40分、そこから市営バス"}]'::jsonb, 'https://www.jleague.jp/club/kagoshima/stadium/', '2026-27 の無料シャトルバスは未確認', null, '{"type":"city","id":6263,"name":"鹿児島"}'::jsonb, '2026-11-07') on conflict do nothing;
insert into public.stadiums (id, name, prefecture, address, lat, lng, stations, airports, access_url, shuttle_note, parking_note, agoda_area, verified_at) values ('hanazono-rugby', '東大阪市花園ラグビー場', '大阪府', '大阪府東大阪市松原南1丁目1-1', 34.668917, 135.62625, '[{"name":"東花園","kind":"nearest","walk_min":8,"note":"近鉄奈良線","toyoko":[]},{"name":"吉田","kind":"nearest","walk_min":15,"note":"近鉄けいはんな線・大阪メトロ中央線","toyoko":[]}]'::jsonb, '[]'::jsonb, 'https://hanazono-rugby-hos.com/access/', 'シャトルバスの案内はない（2026-11-07 時点）', '周辺は住宅地で駐車場が少なく、公共交通を使うよう案内されている。有料の花園中央公園駐車場がある', '{"type":"city","id":18826,"name":"東大阪"}'::jsonb, '2026-11-07') on conflict do nothing;
insert into public.stadiums (id, name, prefecture, address, lat, lng, stations, airports, access_url, shuttle_note, parking_note, agoda_area, verified_at) values ('ningineer-stadium', 'ニンジニアスタジアム', '愛媛県', '愛媛県松山市上野町乙46', 33.7682, 132.7976, '[{"name":"松山市","kind":"bus","walk_min":null,"note":"伊予鉄バス「えひめこどもの城」行きで「ニンスタ前」まで約30〜35分。帰りの最終便が早いので要確認","toyoko":[]},{"name":"松山","kind":"bus","walk_min":null,"note":"JR四国バス久万高原線で「総合運動公園口」下車（約35〜40分）、徒歩約900m","toyoko":[]}]'::jsonb, '[{"iata":"MYJ","name":"松山空港","station":null,"access_min":70,"note":"リムジンバスで松山市駅まで約20〜30分、そこから伊予鉄バス"}]'::jsonb, 'https://ehimefc.com/access/ningineerstadium.html', '通常のシャトルバスはない。帰りの臨時バスが出る試合がある（事前予約）', '普通車300円。満車になると臨時駐車場に誘導される。来場者が多いと足りない', '{"type":"city","id":9590,"name":"松山"}'::jsonb, '2026-11-07') on conflict do nothing;
